package org.securemail.identity;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import org.securemail.ecosystem.protocol.IdentityProtocol.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
/** First delegation is a narrow 4-proof bootstrap, never a generic administrator bypass. */
class FirstDelegationTest {
    @TempDir Path home;IdentityStore store;IdentityStoreTest.MutableClock clock;KeyPair service;byte[] audit;Person owner,target,third;
    record Person(KeyPair root,KeyPair device,KeyPair recovery,KeyPair app,String account,String deviceId,long generation) { }
    static KeyPair pair()throws Exception{return KeyPairGenerator.getInstance("Ed25519").generateKeyPair();}
    static byte[] key(KeyPair k){return k.getPublic().getEncoded();}
    @BeforeEach void setup()throws Exception {clock=new IdentityStoreTest.MutableClock();service=pair();audit=new byte[32];new SecureRandom().nextBytes(audit);store=new IdentityStore(home.resolve("identity.db"),service,audit,clock);owner=register();target=register();third=register();IdentityStore.OwnerChallenge c=store.ownerChallenge(owner.account);store.bootstrapOwner(owner.account,c.challenge(),IdentityProtocol.sign(owner.root.getPrivate(),IdentityProtocol.ownerBootstrap(store.audience(),owner.account,c.challenge(),c.expiresAt())));}
    @AfterEach void close()throws Exception {store.close();}
    Person register()throws Exception {KeyPair r=pair(),d=pair(),recovery=pair(),app=pair();String nonce=IdentityProtocol.nonce();byte[] b=IdentityProtocol.registration(store.audience(),key(r),key(d),key(recovery),"Участник",clock.millis(),nonce);IdentityStore.Session s=store.register(key(r),key(d),key(recovery),"Участник",clock.millis(),nonce,IdentityProtocol.sign(r.getPrivate(),b),IdentityProtocol.sign(d.getPrivate(),b));return new Person(r,d,recovery,app,s.accountId(),s.deviceId(),s.generation());}
    Capability admin(Person p){IdentityStore.Challenge c=store.stepUpChallenge(p.account,p.deviceId,p.generation);byte[] b=IdentityProtocol.stepUp(store.audience(),p.account,p.deviceId,c.challenge(),c.expiresAt());store.stepUp(p.account,p.deviceId,p.generation,c.challenge(),IdentityProtocol.sign(p.root.getPrivate(),b),IdentityProtocol.sign(p.device.getPrivate(),b));String n=IdentityProtocol.nonce();byte[] request=IdentityProtocol.capabilityRequest(store.audience(),p.account,p.deviceId,p.generation,App.AEGIS,key(p.app),EnumSet.of(Scope.ADMIN),600000,clock.millis(),n);return store.issueCapability(p.account,p.deviceId,p.generation,App.AEGIS,key(p.app),EnumSet.of(Scope.ADMIN),600000,clock.millis(),n,IdentityProtocol.sign(p.device.getPrivate(),request),IdentityProtocol.sign(p.app.getPrivate(),request));}
    Map<String,Object> challenge(Capability cap,Person selected,String role){String n=IdentityProtocol.nonce();byte[] proposal=IdentityProtocol.firstDelegateProposal(store.audience(),owner.account,selected.account,role,clock.millis(),n);return store.firstDelegateChallenge(cap,selected.account,role,clock.millis(),n,IdentityProtocol.sign(owner.app.getPrivate(),IdentityProtocol.requestDigest(cap,"admin.execute",IdentityProtocol.digest(proposal),clock.millis(),n)));}
    byte[] consent(Map<String,Object> c){byte[] b=IdentityProtocol.firstDelegateConsent((String)c.get("audience"),(String)c.get("ownerAccountId"),(String)c.get("ownerDeviceId"),(Long)c.get("ownerGeneration"),(String)c.get("targetAccountId"),(String)c.get("targetDeviceId"),(Long)c.get("targetGeneration"),(String)c.get("roleName"),(String)c.get("challenge"),(Long)c.get("expiresAt"));assertArrayEquals(b,IdentityProtocol.unb64((String)c.get("proofBytes"),2048));return b;}
    void complete(Map<String,Object> c){byte[] b=consent(c);store.completeFirstDelegation((String)c.get("challenge"),IdentityProtocol.sign(owner.root.getPrivate(),b),IdentityProtocol.sign(owner.device.getPrivate(),b),IdentityProtocol.sign(target.root.getPrivate(),b),IdentityProtocol.sign(target.device.getPrivate(),b));}
    Map<String,Object> permit(Capability first,String operation,byte[] body){String n=IdentityProtocol.nonce();byte[] exact=IdentityProtocol.criticalApproval(store.audience(),owner.account,operation,n,body,clock.millis()+300000);return store.requestCritical(first,operation,body,clock.millis(),n,IdentityProtocol.sign(owner.app.getPrivate(),IdentityProtocol.requestDigest(first,"admin.execute",IdentityProtocol.digest(exact),clock.millis(),n)));}
    void approve(Capability other,Map<String,Object> r,byte[] body){String n=IdentityProtocol.nonce();byte[] exact=IdentityProtocol.criticalApproval(store.audience(),target.account,(String)r.get("operation"),(String)r.get("requestId"),body,(Long)r.get("expiresAt"));store.approveCritical(other,(String)r.get("requestId"),clock.millis(),n,IdentityProtocol.sign(target.app.getPrivate(),IdentityProtocol.requestDigest(other,"admin.execute",IdentityProtocol.digest(exact),clock.millis(),n)));}
    byte[] consumeProof(Capability first,Map<String,Object> r,byte[] body,String nonce){byte[] exact=IdentityProtocol.criticalApproval(store.audience(),owner.account,(String)r.get("operation"),(String)r.get("requestId"),body,(Long)r.get("expiresAt"));return IdentityProtocol.sign(owner.app.getPrivate(),IdentityProtocol.requestDigest(first,"admin.execute",IdentityProtocol.digest(exact),clock.millis(),nonce));}
    @Test void firstDelegationRequiresFourProofsAndGrantsNamedCustomAdministratorOnlyOnce(){Capability ownerCap=admin(owner);Map<String,Object> c=challenge(ownerCap,target,"Смотритель инфраструктуры");byte[] b=consent(c);assertThrows(IdentityException.class,()->store.completeFirstDelegation((String)c.get("challenge"),IdentityProtocol.sign(owner.root.getPrivate(),b),IdentityProtocol.sign(owner.device.getPrivate(),b),IdentityProtocol.sign(target.root.getPrivate(),b),IdentityProtocol.sign(owner.device.getPrivate(),b)));complete(c);assertTrue(store.isActive(admin(target)));assertEquals(false,store.profile(target.account).get("ownerBadge"));assertThrows(IdentityException.class,()->complete(c));assertThrows(IdentityException.class,()->challenge(ownerCap,third,"Ещё один"));assertTrue(store.verifyAudit());}
    @Test void ownerCannotBeOwnIndependentSecondConfirmation(){Capability first=admin(owner);assertThrows(IdentityException.class,()->challenge(first,owner,"Владелец"));}
    @Test void changedRoleNameOrWrongDeviceProofInvalidatesAllConsent(){Capability first=admin(owner);Map<String,Object> c=challenge(first,target,"Оператор");byte[] wrong=IdentityProtocol.firstDelegateConsent(store.audience(),owner.account,owner.deviceId,owner.generation,target.account,target.deviceId,target.generation,"Другой уровень",(String)c.get("challenge"),(Long)c.get("expiresAt"));assertThrows(IdentityException.class,()->store.completeFirstDelegation((String)c.get("challenge"),IdentityProtocol.sign(owner.root.getPrivate(),wrong),IdentityProtocol.sign(owner.device.getPrivate(),wrong),IdentityProtocol.sign(target.root.getPrivate(),wrong),IdentityProtocol.sign(target.device.getPrivate(),wrong)));complete(c);}
    @Test void targetLoginGenerationChangeInvalidatesConsent(){Map<String,Object> c=challenge(admin(owner),target,"Оператор");String n=IdentityProtocol.nonce();store.login(target.account,target.deviceId,clock.millis(),n,IdentityProtocol.sign(target.device.getPrivate(),IdentityProtocol.login(store.audience(),target.account,target.deviceId,clock.millis(),n)));assertThrows(IdentityException.class,()->complete(c));}
    @Test void ownerLoginGenerationChangeInvalidatesConsent(){Map<String,Object> c=challenge(admin(owner),target,"Оператор");String n=IdentityProtocol.nonce();store.login(owner.account,owner.deviceId,clock.millis(),n,IdentityProtocol.sign(owner.device.getPrivate(),IdentityProtocol.login(store.audience(),owner.account,owner.deviceId,clock.millis(),n)));assertThrows(IdentityException.class,()->complete(c));}
    @Test void consentExpiresAfter120Seconds(){Map<String,Object> c=challenge(admin(owner),target,"Оператор");clock.value+=120000;assertThrows(IdentityException.class,()->complete(c));}
    @Test void concurrentCompletionCannotCreateTwoFirstDelegates()throws Exception {Map<String,Object> c=challenge(admin(owner),target,"Оператор");byte[] b=consent(c),or=IdentityProtocol.sign(owner.root.getPrivate(),b),od=IdentityProtocol.sign(owner.device.getPrivate(),b),tr=IdentityProtocol.sign(target.root.getPrivate(),b),td=IdentityProtocol.sign(target.device.getPrivate(),b);try(IdentityStore second=new IdentityStore(home.resolve("identity.db"),service,audit,clock)){ExecutorService pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);try{java.util.function.Function<IdentityStore,Boolean> finish=s->{try{s.completeFirstDelegation((String)c.get("challenge"),or,od,tr,td);return true;}catch(IdentityException denied){return false;}};Future<Boolean>a=pool.submit(()->{start.await();return finish.apply(store);}),other=pool.submit(()->{start.await();return finish.apply(second);});start.countDown();assertNotEquals(a.get(5,TimeUnit.SECONDS),other.get(5,TimeUnit.SECONDS));assertTrue(store.isActive(admin(target)));}finally{pool.shutdownNow();}}}
    @Test void normalSubsequentAssignmentRequiresTwoCurrentAdministrators(){Capability first=admin(owner);complete(challenge(first,target,"Оператор"));Capability second=admin(target);byte[] body=IdentityProtocol.administratorAssignment(third.account,"Редактор безопасности");Map<String,Object> r=permit(first,"administrator.assign",body);String failedNonce=IdentityProtocol.nonce();assertThrows(IdentityException.class,()->store.assignAdministrator(first,(String)r.get("requestId"),third.account,"Редактор безопасности",clock.millis(),failedNonce,consumeProof(first,r,body,failedNonce)));approve(second,r,body);String n=IdentityProtocol.nonce();store.assignAdministrator(first,(String)r.get("requestId"),third.account,"Редактор безопасности",clock.millis(),n,consumeProof(first,r,body,n));assertTrue(store.isActive(admin(third)));assertEquals(false,store.profile(third.account).get("ownerBadge"));}
    @Test void recoveredAccountCanRegainLibraryOnlyAfterTwoAdministratorReview()throws Exception {Capability first=admin(owner);complete(challenge(first,target,"Оператор"));Capability second=admin(target);KeyPair newDevice=pair();String n=IdentityProtocol.nonce();IdentityStore.DeviceChallenge dc=store.challengeDevice(third.account,key(newDevice),clock.millis(),n,IdentityProtocol.sign(newDevice.getPrivate(),IdentityProtocol.login(store.audience(),third.account,IdentityProtocol.id(key(newDevice)),clock.millis(),n)));byte[] recovery=IdentityProtocol.recovery(store.audience(),third.account,dc.challenge(),key(newDevice),dc.expiresAt());store.recoverDevice(third.account,dc.challenge(),IdentityProtocol.sign(third.root.getPrivate(),recovery),IdentityProtocol.sign(third.recovery.getPrivate(),recovery));assertEquals(true,store.profile(third.account).get("sensitiveRecoveryPending"));byte[] body=IdentityProtocol.accountRecoveryApproval(third.account);Map<String,Object> permit=permit(first,"account.sensitive_recovery.approve",body);String failed=IdentityProtocol.nonce();assertThrows(IdentityException.class,()->store.approveSensitiveRecovery(first,(String)permit.get("requestId"),third.account,clock.millis(),failed,consumeProof(first,permit,body,failed)));approve(second,permit,body);String finish=IdentityProtocol.nonce();store.approveSensitiveRecovery(first,(String)permit.get("requestId"),third.account,clock.millis(),finish,consumeProof(first,permit,body,finish));assertEquals(false,store.profile(third.account).get("sensitiveRecoveryPending"));}
    @Test void revokingAllDelegatesDoesNotResetOneTimeFirstBootstrap(){Capability first=admin(owner);complete(challenge(first,target,"Оператор"));Capability second=admin(target);byte[] body=IdentityProtocol.administratorRevocation(target.account);Map<String,Object> r=permit(first,"administrator.revoke",body);approve(second,r,body);String n=IdentityProtocol.nonce();store.revokeAdministrator(first,(String)r.get("requestId"),target.account,clock.millis(),n,consumeProof(first,r,body,n));assertFalse(store.isActive(second));assertThrows(IdentityException.class,()->admin(target));assertThrows(IdentityException.class,()->challenge(first,third,"Новый оператор"));}
}
